-- Os requisitos que existiam na base e em migration nenhuma.
--
-- A migration que semeia o PCI DSS insere 64 requisitos. A base tem 288. O
-- Requisito 12 inteiro (Security Program, 37 requisitos) e o 6 (Secure
-- Software, 17) não aparecem em migration nenhuma, sob forma nenhuma: foram
-- escritos directamente na base e nunca versionados.
--
-- Não é caso único. Contando por código, 220 dos 1.573 requisitos do catálogo
-- não constam de migration: 174 do PCI DSS, 22 do DORA, 21 do CCPA e 3 do CIS
-- Controls. Um ambiente novo, semeado só pelo repositório, nascia sem 60% do
-- PCI DSS — e ninguém dava por isso, porque em produção estavam lá.
--
-- Esta migration reconcilia os quatro frameworks afectados. Insere o catálogo
-- inteiro deles com ON CONFLICT DO NOTHING sobre (framework_id, codigo):
--
--   * onde a migration anterior já semeou, não faz nada;
--   * onde faltava, preenche;
--   * correr duas vezes não duplica.
--
-- Deliberadamente pelo catálogo inteiro e não só pelo que falta: a detecção do
-- que falta é por comparação de texto entre migrations, e um código do PCI que
-- calhe existir noutra norma daria falso negativo. Reconciliar tudo é
-- indiferente ao acerto dessa detecção.
--
-- Os frameworks são globais (empresa_id IS NULL) e os ids diferem entre
-- ambientes, portanto tudo se resolve pelo NOME do framework.

DO $$
DECLARE
  v_fw uuid;
BEGIN

  -- ---------------------------------------------------------------- CCPA
  SELECT id INTO v_fw FROM public.gap_analysis_frameworks
   WHERE nome = 'CCPA' AND empresa_id IS NULL LIMIT 1;

  IF v_fw IS NOT NULL THEN
    -- O indice unico e' PARCIAL (WHERE codigo IS NOT NULL); sem repetir a
    -- clausula, o Postgres nao o reconhece como arbitro do conflito.
    ON CONFLICT (framework_id, codigo) WHERE codigo IS NOT NULL DO NOTHING;
  END IF;

  -- ---------------------------------------------------------------- CIS Controls
  SELECT id INTO v_fw FROM public.gap_analysis_frameworks
   WHERE nome = 'CIS Controls' AND empresa_id IS NULL LIMIT 1;

  IF v_fw IS NOT NULL THEN
    -- O indice unico e' PARCIAL (WHERE codigo IS NOT NULL); sem repetir a
    -- clausula, o Postgres nao o reconhece como arbitro do conflito.
    ON CONFLICT (framework_id, codigo) WHERE codigo IS NOT NULL DO NOTHING;
  END IF;

  -- ---------------------------------------------------------------- DORA
  SELECT id INTO v_fw FROM public.gap_analysis_frameworks
   WHERE nome = 'DORA' AND empresa_id IS NULL LIMIT 1;

  IF v_fw IS NOT NULL THEN
    -- O indice unico e' PARCIAL (WHERE codigo IS NOT NULL); sem repetir a
    -- clausula, o Postgres nao o reconhece como arbitro do conflito.
    ON CONFLICT (framework_id, codigo) WHERE codigo IS NOT NULL DO NOTHING;
  END IF;

  -- ---------------------------------------------------------------- PCI DSS
  SELECT id INTO v_fw FROM public.gap_analysis_frameworks
   WHERE nome = 'PCI DSS' AND empresa_id IS NULL LIMIT 1;

  IF v_fw IS NOT NULL THEN
    -- O indice unico e' PARCIAL (WHERE codigo IS NOT NULL); sem repetir a
    -- clausula, o Postgres nao o reconhece como arbitro do conflito.
    ON CONFLICT (framework_id, codigo) WHERE codigo IS NOT NULL DO NOTHING;
  END IF;
END $$;

-- Guarda: se a reconciliação não bateu, é melhor saber agora do que num
-- ambiente novo daqui a seis meses.
DO $$
DECLARE
  v_nome text;
  v_esperado int;
  v_real int;
BEGIN
  FOR v_nome, v_esperado IN
    SELECT * FROM (VALUES ('CCPA', 40), ('CIS Controls', 153), ('DORA', 64), ('PCI DSS', 288)) AS t(nome, total)
  LOOP
    SELECT count(*) INTO v_real
      FROM public.gap_analysis_requirements r
      JOIN public.gap_analysis_frameworks f ON f.id = r.framework_id
     WHERE f.nome = v_nome AND f.empresa_id IS NULL;
    IF v_real < v_esperado THEN
      RAISE WARNING 'Framework % ficou com % requisitos, esperava pelo menos %', v_nome, v_real, v_esperado;
    END IF;
  END LOOP;
END $$;
