      (v_fw, '1798.185', 'Regulamentos da Procuradoria-Geral', 'Conformidade com regulamentos adotados pela Procuradoria-Geral da Califórnia', 'Compliance', 20, 2, true, 'Compliance'),
      (v_fw, '1798.100(a)(1)', 'Aviso no momento da coleta', 'Informar consumidores, no momento ou antes da coleta, sobre as categorias de dados coletados, finalidades e período de retenção.', 'Transparência', 100, 1, true, NULL),
      (v_fw, '1798.100(b)', 'Resposta a solicitações do titular', 'Responder a solicitações verificáveis do consumidor em até 45 dias, prorrogáveis por mais 45 dias mediante justificativa.', 'Direitos do Titular', 101, 1, true, NULL),
