      (v_fw, '1798.100(d)', 'Contratos com service providers, contractors e third parties', 'Formalizar contratos escritos com service providers, contractors e third parties que restrinjam finalidades e obriguem a mesmos deveres do CPRA.', 'Terceiros', 103, 1, true, NULL),
      (v_fw, '1798.100(e)', 'Medidas razoáveis de segurança', 'Implementar e manter procedimentos e práticas razoáveis de segurança apropriados à natureza dos dados pessoais.', 'Segurança', 104, 1, true, NULL),
