      (v_fw, '1798.121', 'Direito de limitar uso de SPI', 'Permitir ao consumidor limitar o uso e divulgação de sensitive personal information (SPI) a finalidades estritamente necessárias.', 'Direitos do Titular', 121, 1, true, NULL),
      (v_fw, '1798.125', 'Não discriminação e incentivos financeiros', 'Proibir tratamento discriminatório contra consumidores que exercem direitos; permitir incentivos financeiros com prévia autorização.', 'Direitos do Titular', 125, 1, true, NULL),
      (v_fw, '1798.130(a)(5)', 'Divulgações na política de privacidade', 'Publicar política de privacidade com categorias coletadas nos últimos 12 meses, direitos, canais de contato e métodos de solicitação.', 'Transparência', 130, 1, true, NULL),
      (v_fw, '1798.135(c)', 'Link alternativo único de opt-out', 'Oferecer link único "Your Privacy Choices" que combine opt-out de venda/compartilhamento e limitação de SPI.', 'Direitos do Titular', 135, 1, true, NULL),
      (v_fw, '1798.140(ae)', 'Definição de Sensitive Personal Information', 'Identificar e classificar SPI conforme definição do CPRA: SSN, geolocalização precisa, credenciais, saúde, orientação sexual, etnia, etc.', 'Classificação', 140, 1, true, NULL),
      (v_fw, '1798.140(v)', 'Definição de Personal Information', 'Manter classificação alinhada à definição ampla de dado pessoal do CCPA/CPRA (inclui identificadores online, inferências).', 'Classificação', 141, 1, true, NULL),
      (v_fw, '1798.145.5', 'Dados desidentificados e agregados', 'Ao alegar desidentificação, manter salvaguardas técnicas e contratuais que impeçam reidentificação.', 'Minimização', 145, 1, true, NULL),
      (v_fw, '1798.148', 'Proibição de declarações falsas', 'Proibir declarações falsas ou enganosas em avisos, políticas e formulários de solicitação.', 'Transparência', 148, 1, true, NULL),
      (v_fw, '1798.175', 'Interpretação e severabilidade', 'Aplicar a norma preservando validade das demais disposições em caso de invalidação parcial.', 'Governança', 175, 1, false, NULL),
      (v_fw, '1798.185(a)(15)', 'Avaliações de risco (Risk Assessments)', 'Realizar avaliações de risco quando o tratamento apresentar risco significativo à privacidade ou segurança do consumidor.', 'Governança', 185, 1, true, NULL),
      (v_fw, '1798.185(a)(16)', 'Ciber-auditoria anual', 'Realizar auditorias anuais de cibersegurança para negócios cujo tratamento apresente risco significativo.', 'Governança', 186, 1, true, NULL),
      (v_fw, '1798.190', 'Anti-retaliação para funcionários', 'Proibir retaliação contra empregados que exercem ou promovem direitos previstos no CPRA.', 'Governança', 190, 1, true, NULL),
      (v_fw, '1798.192', 'Renúncia de direitos inválida', 'Considerar nula qualquer cláusula contratual que exija renúncia dos direitos do consumidor sob CCPA/CPRA.', 'Governança', 192, 1, true, NULL),
      (v_fw, '1798.199.40', 'Autoridade da CPPA', 'Cooperar com a California Privacy Protection Agency (CPPA) em fiscalizações, requisições e regulamentações.', 'Governança', 199, 1, true, NULL),
      (v_fw, '1798.199.45', 'Enforcement pela CPPA', 'Sujeitar-se a fiscalização, penalidades administrativas e ordens da CPPA por violações do CPRA.', 'Governança', 200, 1, true, NULL)
