      (v_fw, 'DORA-OV-01', 'Sujeição ao Oversight Framework de CTPPs', 'Ser identificado como Critical ICT Third-Party Provider (CTPP) sujeita a supervisão da Lead Overseer (Art. 31).', 'Supervisão CTPP', 1001, 1, false, NULL),
      (v_fw, 'DORA-OV-02', 'Poderes da Lead Overseer', 'Atender solicitações da Lead Overseer, incluindo inspeções, testes e requisições de informação (Art. 35).', 'Supervisão CTPP', 1002, 1, false, NULL),
      (v_fw, 'DORA-OV-03', 'Recomendações da Lead Overseer', 'Endereçar recomendações emitidas pela Lead Overseer no prazo definido (Art. 42).', 'Supervisão CTPP', 1003, 1, false, NULL),
      (v_fw, 'DORA-OV-04', 'Cooperação com Joint Oversight Network', 'Participar da cooperação entre autoridades europeias (JON) para supervisão convergente de CTPPs (Art. 32-34).', 'Supervisão CTPP', 1004, 1, false, NULL),
      (v_fw, 'DORA-OV-05', 'Penalidades periódicas por descumprimento', 'Estar ciente e mitigar risco de penalidades periódicas coercitivas por descumprimento (Art. 35(6)).', 'Supervisão CTPP', 1005, 1, false, NULL)
    INSERT INTO public.gap_analysis_requirements
      (framework_id, codigo, titulo, descricao, categoria, ordem, peso, obrigatorio, area_responsavel)
    VALUES
      (v_fw, '1.1', 'Instalar e Manter Controles de Segurança de Rede', 'Instalar e manter controles de segurança de rede (NSCs) para proteger dados em ambientes de rede.', 'Network Security', 1, 3, true, 'Segurança'),
      (v_fw, '1.1.1', 'Políticas e Procedimentos de Segurança', 'Processos e mecanismos para instalar e manter controles de segurança de rede estão definidos e documentados.', 'Network Security', 2, 3, true, 'Segurança'),
      (v_fw, '1.2', 'Configurar Controles de Segurança de Rede', 'Os controles de segurança de rede (NSCs) são configurados e mantidos para restringir conexões e tráfego de rede.', 'Network Security', 3, 3, true, 'Segurança'),
      (v_fw, '1.2.1', 'Padrões de Configuração', 'Padrões de configuração para NSCs estão definidos e implementados.', 'Network Security', 4, 3, true, 'Segurança'),
      (v_fw, '1.2.2', 'Restrição de Tráfego de Entrada', 'Todo o tráfego de entrada de redes não confiáveis para redes confiáveis é restrito.', 'Network Security', 5, 3, true, 'Segurança'),
      (v_fw, '1.2.3', 'Restrição de Tráfego de Saída', 'Todo o tráfego de saída do CDE é restrito.', 'Network Security', 6, 3, true, 'Segurança'),
      (v_fw, '1.2.4', 'Medidas Anti-Spoofing', 'Medidas anti-spoofing são implementadas para detectar e bloquear endereços IP de origem forjados.', 'Network Security', 7, 3, true, 'Segurança'),
      (v_fw, '1.2.5', 'Segmentação de Rede', 'O ambiente de dados do titular do cartão (CDE) é segmentado de todas as demais redes.', 'Network Security', 8, 3, true, 'Segurança'),
